from pathlib import Path
from dataclasses import replace
import json,hashlib,subprocess
from snail import match as m
from snail.symbols import load_function_symbol_manifest
out=Path('/tmp/snail-goal-family-uv');root=Path('tools/match');manifest=load_function_symbol_manifest(Path('analysis/symbols/gameplay-functions.json'));image=m.load_image(Path(manifest.primary_target),manifest.image_base)
proof={'schema':1,'date':'2026-09-11','baseline_commit':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'description':'Partial source recoveries for Cage2, Screw and Turnunder. No normalized or encoded exact credit is claimed.','functions':[],'forward_controls':{},'reverse_controls':{},'mobile_and_windows_source_witnesses':[]}
for short in ['cage2','screw','turnunder']:
 p=root/'scratches'/('initialize_'+short+'_path_template_pair');c=m.load_scratch_config(p);start,end=m.resolve_function_extent(manifest,c.function,c.end_va);native=image.function_bytes(start,end);entry={'function':c.function,'native_address':start,'native_bytes':native.hex(),'versions':{}}
 for label,source in [('baseline',(out/short/'baseline.cpp').read_text()),('retained',(p/'scratch.cpp').read_text())]:
  d=out/short/('compile-proof-'+label);d.mkdir(exist_ok=True);(d/'scratch.cpp').write_text(source);conf=(p/'scratch.conf').read_text()
  if label=='baseline' and short=='screw':conf=conf.replace('RESIDUAL=analysis','RESIDUAL=analysis,references')
  (d/'scratch.conf').write_text(conf);cfg=replace(c,directory=d);matches=[];status=m.scratch_status_payload(m.evaluate_scratch(cfg,on_match=matches.append));res=matches[0];obj=m.extract_object_function(m.parse_coff_object(m.compile_scratch(cfg,m.DEFAULT_MATCH_ROOT).read_bytes()),c.symbol or c.function);audit=m._masked_audit_cache_payload(res.masked_operand_audit)
  if label=='retained':assert all(x['status']=='ok' for x in audit);assert not status['body_byte_exact'];assert status['match_ratio']<1
  entry['versions'][label]={'source':source,'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'status':status,'candidate_unlinked_bytes':obj.data.hex(),'target_instructions':[{'index':idx,'offset':i.offset,'text':i.text,'raw':native[i.offset:i.offset+i.size].hex()} for idx,i in enumerate(res.target_disassembly)],'candidate_instructions':[{'index':idx,'offset':i.offset,'text':i.text,'raw':obj.data[i.offset:i.offset+i.size].hex()} for idx,i in enumerate(res.candidate_disassembly)],'reference_audit':audit,'stack_frame':m.stack_frame_diagnostic_payload(res)}
  print(short,label,status['match_ratio'],status['references'],flush=True)
 proof['functions'].append(entry)
for short in ['cage2','invert','screw','toad','turnover','turnunder']:
 proof['forward_controls'][short]=json.loads((out/short/'recorded-forward.json').read_text())
 if (out/short/'recorded-reverse.json').exists():proof['reverse_controls'][short]=json.loads((out/short/'recorded-reverse.json').read_text())
for p in [Path('analysis/decompile/ida/functions/0041eda0-initialize_screw_path_template_pair.c'),Path('analysis/decompile/binja/functions/0041eda0-initialize_screw_path_template_pair.c'),Path('analysis/decompile/android/functions/0005681c-_ZN6cRPath10BuildScrewEiibPcS0_.c'),Path('analysis/decompile/ios/functions/000586dc-_ZN6cRPath10BuildScrewEiibPcS0_.c')]:
 b=p.read_bytes();proof['mobile_and_windows_source_witnesses'].append({'path':str(p),'sha256':hashlib.sha256(b).hexdigest(),'text':b.decode()})
proof['measurement_identities']=json.loads(Path('analysis/progress/win32-reflexive.json').read_text())['identities'];proof['proof_script']=Path(__file__).read_text()
def render(v,depth=0):
 pad='  '*depth
 if isinstance(v,dict):return '{\n'+',\n'.join('  '*(depth+1)+json.dumps(k)+': '+render(x,depth+1) for k,x in v.items())+'\n'+pad+'}'
 if isinstance(v,list):
  if not v or all(not isinstance(x,(dict,list)) for x in v):return json.dumps(v)
  if all(isinstance(x,dict) and ('index' in x or 'target_index' in x) for x in v):return '[\n'+',\n'.join('  '*(depth+1)+json.dumps(x,separators=(',',':')) for x in v)+'\n'+pad+']'
  return '[\n'+',\n'.join('  '*(depth+1)+render(x,depth+1) for x in v)+'\n'+pad+']'
 return json.dumps(v)
s=render(proof)+'\n';assert json.loads(s)==proof;(root/'path-uv-and-screw-owners-20260911.json').write_text(s)
